<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { platformApi, request } from '../api'; import PageHeader from '../components/PageHeader.vue'; import ResourceState from '../components/ResourceState.vue'; import type { RuntimeEvent } from '../types'
const events = ref<RuntimeEvent[]>([]); const loading = ref(true); const error = ref(''); onMounted(async () => { try { const devices = await platformApi.devices(); if (devices[0]) events.value = await request(`/api/v1/devices/${encodeURIComponent(devices[0].deviceId)}/events`) } catch (cause) { error.value = String(cause) } finally { loading.value = false } })
</script>
<template><main class="content"><PageHeader eyebrow="Observe" title="Runtime event stream" description="Read commit-ordered device, command, scenario, and fault activity emitted by the backend runtime." /><ResourceState :loading="loading" :error="error" :empty="events.length === 0" empty-text="No runtime events have been emitted."><div class="event-terminal expanded"><div v-for="(event, index) in events.slice().reverse()" :key="index" class="event-row"><span class="event-time">{{ events.length - index }}</span><span class="event-type">{{ event.eventType ?? event.type ?? 'RuntimeEvent' }}</span><span class="event-data">{{ JSON.stringify(event) }}</span></div></div></ResourceState></main></template>
